  const name = field('name',120); const email = field('email',254).toLowerCase(); const topic = field('topic',1000,false);
  if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) throw new Error('Invalid email');
  const start = field('start',40);
